/* Grade 8 multiple-choice tests (part 2): Life Orientation, Creative Arts, English and Afrikaans.
   Uses defineSets from tests-g8.js and M, placeMC, MC_INTRO from tests-g7.js. */

/* Language tests: a reading passage with 6 questions, then 34 language questions taken from two pools (17 + 17). */
function defineLang(prefix, grade, subject, name, what, langHead, passages, A, B, shift){
  for(let t=0;t<3;t++){
    const a = A.filter((_,i)=>i%3===t), b = B.filter((_,i)=>i%3===t), lang = [];
    for(let i=0;i<Math.max(a.length,b.length);i++){ if(a[i]) lang.push(a[i]); if(b[i]) lang.push(b[i]); }
    const P = passages[t];
    defineTest(`${prefix}-t${t+1}`, {grade, subject, kind:"mc", minutes:30,
      title:`${name} Test ${t+1} · Multiple choice`, intro:MC_INTRO(what),
      mc:placeMC([{head:P.head}, ...P.qs, {head:langHead}, ...lang], shift + t*7)});
  }
}

